```python
from cyclopts import App

app = App(name="myservice")


@app.command
def start():
    """Start the service."""
    print("Starting service...")


@app.command
def stop():
    """Stop the service."""
    print("Stopping service...")


@app.default
def status():
    """Show service status (runs when invoked with no subcommand)."""
    print("Service status: unknown")


if __name__ == "__main__":
    app()
